import { startVitest } from "file:///D:/projexts/moe-next/node_modules/vitest/dist/node.js";
const drill = DRILL_JSON;
let transformed = 0;
const plugin = { name: "set-target-drill", enforce: "pre", transform(source, id) {
  if (!id.replaceAll("\\", "/").split("?")[0].endsWith("/src/" + drill.file)) return;
  let code = source;
  for (const [from, to] of drill.changes) {
    if (code.split(from).length !== 2) throw new Error("Mutation anchor must match exactly once");
    code = code.replace(from, to);
  }
  transformed++;
  return { code, map: null };
}};
let ctx;
try {
  ctx = await startVitest("test", drill.tests, {
    root: "D:/projexts/moe-next/apps/daemon", config: "D:/projexts/moe-next/apps/daemon/package.json",
    run: true, watch: false, maxWorkers: 1, testTimeout: 30000, testNamePattern: drill.pattern
  }, { plugins: [plugin] });
  const walk = task => [task, ...(task.tasks ?? []).flatMap(walk)];
  const tests = ctx.state.getFiles().flatMap(walk).filter(task => task.type === "test");
  const passed = tests.filter(task => task.result?.state === "pass").length;
  const failed = tests.filter(task => task.result?.state === "fail").length;
  const errors = ctx.state.getUnhandledErrors().length;
  console.log("DRILL_SUMMARY " + JSON.stringify({ id: drill.id, transformed, passed, failed, errors }));
  process.exitCode = transformed === 0 || passed + failed === 0 || errors > 0 ? 2 : failed > 0 ? 1 : 0;
} finally { if (ctx) await ctx.close(); }
